package com.sahratalkhamis.couples;
import android.app.*;
import android.content.*;
import android.os.Build;
import java.util.Calendar;
public class AlarmReceiver extends BroadcastReceiver {
 static PendingIntent pending(Context c,String action,int id){Intent i=new Intent(c,AlarmReceiver.class).setAction(action);return PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void cancel(Context c,String a,int id){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(pending(c,a,id));}
 static void scheduleReminder(Context c,int h,int m){Calendar d=Calendar.getInstance();d.set(Calendar.DAY_OF_WEEK,Calendar.THURSDAY);d.set(Calendar.HOUR_OF_DAY,h);d.set(Calendar.MINUTE,m);d.set(Calendar.SECOND,0);d.set(Calendar.MILLISECOND,0);if(d.getTimeInMillis()<=System.currentTimeMillis())d.add(Calendar.WEEK_OF_YEAR,1);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,d.getTimeInMillis(),pending(c,"reminder",10));}
 static void scheduleDnd(Context c,long end){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,pending(c,"dnd",11));}
 static void restoreDnd(Context c){android.content.SharedPreferences p=c.getSharedPreferences("sahra",0);if(p.getLong("dndEnd",0)==0)return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(nm.isNotificationPolicyAccessGranted() && nm.getCurrentInterruptionFilter()==NotificationManager.INTERRUPTION_FILTER_NONE)nm.setInterruptionFilter(p.getInt("dndPrevious",NotificationManager.INTERRUPTION_FILTER_ALL));p.edit().putLong("dndEnd",0).apply();cancel(c,"dnd",11);}
 @Override public void onReceive(Context c,Intent i){if("dnd".equals(i.getAction())){restoreDnd(c);return;}if(!"reminder".equals(i.getAction()))return;android.content.SharedPreferences p=c.getSharedPreferences("sahra",0);if(!p.getBoolean("reminder",false))return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel("thursday","تذكير سهرة الخميس",NotificationManager.IMPORTANCE_DEFAULT));Intent launch=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,0,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"thursday"):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("موعد سهرة الخميس 🕯️").setContentText("وقتكم مع بعض.. جهزوا أجواء سهرتكم ❤️").setAutoCancel(true).setContentIntent(pi);try{nm.notify(12,b.build());}catch(SecurityException ignored){}scheduleReminder(c,p.getInt("hour",21),p.getInt("minute",0));}
}
